CREATE TABLE IF NOT EXISTS payment_installments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, installment_type VARCHAR(50) NOT NULL, sequence_no INT NOT NULL, due_date DATE NOT NULL, amount NUMERIC(15,2) NOT NULL, paid_amount NUMERIC(15,2) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', remarks VARCHAR(500), created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(booking_id,sequence_no));
ALTER TABLE customer_payments ADD COLUMN IF NOT EXISTS installment_id UUID REFERENCES payment_installments(id);
ALTER TABLE customer_payments ADD COLUMN IF NOT EXISTS approved_by UUID REFERENCES users(id);
ALTER TABLE customer_payments ADD COLUMN IF NOT EXISTS reversed_at TIMESTAMPTZ;
ALTER TABLE customer_payments ADD COLUMN IF NOT EXISTS reversal_reason VARCHAR(500);
CREATE TABLE IF NOT EXISTS payment_adjustments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payment_id UUID NOT NULL REFERENCES customer_payments(id), adjustment_type VARCHAR(30) NOT NULL, amount NUMERIC(15,2) NOT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_by UUID REFERENCES users(id), approved_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bank_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), entry_date DATE NOT NULL, bank_name VARCHAR(120) NOT NULL, entry_type VARCHAR(20) NOT NULL, amount NUMERIC(15,2) NOT NULL, reference_number VARCHAR(120), description VARCHAR(500), reconciled BOOLEAN NOT NULL DEFAULT FALSE, created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS collection_targets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), month_start DATE NOT NULL, project_id UUID REFERENCES projects(id), target_amount NUMERIC(15,2) NOT NULL, achieved_amount NUMERIC(15,2) NOT NULL DEFAULT 0, created_by UUID REFERENCES users(id), UNIQUE(month_start,project_id));
CREATE INDEX IF NOT EXISTS idx_installments_due_status ON payment_installments(due_date,status);
CREATE INDEX IF NOT EXISTS idx_customer_payments_date_status ON customer_payments(payment_date,status);
